package com.ecommerce.controller;
import com.ecommerce.dto.CatalogDtos.*; import com.ecommerce.service.CatalogService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api") public class CatalogController { private final CatalogService catalog; public CatalogController(CatalogService catalog){this.catalog=catalog;} @GetMapping("/health") public String health(){return "E-Commerce backend is running";} @GetMapping("/categories") public List<CategoryResponse> categories(){return catalog.categories();} @GetMapping("/products") public List<ProductResponse> products(@RequestParam(required=false) String category){return catalog.products(category);} @GetMapping("/products/search") public List<ProductResponse> search(@RequestParam String q){return catalog.search(q);} @GetMapping("/products/{id}") public ProductResponse product(@PathVariable Long id){return catalog.product(id);} }